#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

#
# The deploy checklist decided in #109, as a wizard (#136): the one-time setup of
# Google, WorkOS, Railway, Hostinger and GitHub, then the first deploy and its checks.
#
#   scripts/deploy_wizard.sh
#
# Values are kept in ~/.config/knowledge-pool/deploy.env so a re-run remembers
# them, but only the public ones: the WorkOS API key and the cookie password
# live in Railway (sealed) and your password manager, never on disk (#109).
# What the checks find is written to deploy-notes.md beside it, and the last
# stage offers to post it to #136.

APP_HOST="knowledge-pool.engi.ai"
APP_URL="https://$APP_HOST"
MCP_URL="$APP_URL/mcp"
HEALTH_PATH="/healthz"
CALLBACK_URL="$APP_URL/auth/callback"
REPO="DaveParr/knowledge-pool"
ISSUE=136

STATE_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/knowledge-pool"
mkdir -p "$STATE_DIR"
ENV_FILE="$STATE_DIR/deploy.env"
NOTES_FILE="$STATE_DIR/deploy-notes.md"

# record "Topic" "finding" appends one finding to the notes file.
record() {
  [[ -f "$NOTES_FILE" ]] || printf '## First deploy: notes from the deploy wizard\n\n' > "$NOTES_FILE"
  printf -- '- **%s**: %s\n' "$1" "$2" >> "$NOTES_FILE"
  printf '  %s✓ noted%s %s\n' "$GREEN" "$RESET" "$1"
}

# ask_note "Topic" "Prompt" asks for a finding and records it (nothing typed: nothing recorded).
ask_note() {
  local finding=""
  printf '  %s%s%s ' "$BOLD" "$2" "$RESET"
  read -r finding || true
  [[ -n "$finding" ]] && record "$1" "$finding"
  return 0
}

# status_of METHOD PATH [curl args...] prints the HTTP status of one request to the app.
status_of() {
  local method="$1" path="$2"; shift 2
  curl -s -o /dev/null -w '%{http_code}' -X "$method" --max-time 20 "$@" "$APP_URL$path" || printf '000'
}

# expect_status "what" WANT GOT prints a pass or a failure line and records failures.
expect_status() {
  if [[ "$3" == "$2" ]]; then
    printf '  %s✓%s %s: %s\n' "$GREEN" "$RESET" "$1" "$3"
  else
    printf '  %s✗ %s: wanted %s, got %s%s\n' "$RED" "$1" "$2" "$3" "$RESET"
    record "Check failed" "$1: wanted $2, got $3"
  fi
}

TOTAL_STAGES=21

banner "Knowledge Pool: deploy checklist and first deploy"

# ── A. One-time setup ─────────────────────────────────────────────────────

stage "Accounts: two-factor sign-in and sole access"
say "Every account that can change the app must have two-factor sign-in on."
step "GitHub, Railway, WorkOS, Hostinger and the Google account that will own the OAuth client."
open_url "https://github.com/settings/security"
pause "Press Enter once all five have two-factor sign-in on."
say "You must be the only collaborator on the repo (checked now)."
if command -v gh >/dev/null 2>&1 && others=$(gh api "repos/$REPO/collaborators" --jq '.[].login' 2>/dev/null); then
  note "collaborators: $(printf '%s' "$others" | tr '\n' ' ')"
  [[ $(printf '%s\n' "$others" | grep -c .) -eq 1 ]] || warn "more than one collaborator: remove the others at github.com/$REPO/settings/access"
else
  open_url "https://github.com/$REPO/settings/access"
fi
pause

stage "Hostinger: the engi.ai expiry date"
say "The domain must never lapse: connectors would point at whoever registers it next (ADR 0002)."
open_url "https://hpanel.hostinger.com/domains"
step "Find engi.ai and check auto-renew is on."
ask ENGI_AI_EXPIRY "Expiry date shown for engi.ai (YYYY-MM-DD):"
write_env ENGI_AI_EXPIRY "$ENGI_AI_EXPIRY"
record "engi.ai expiry" "$ENGI_AI_EXPIRY (auto-renew on, at Hostinger)"
pause

stage "WorkOS: Production environment and its organization"
say "The hosted app uses WorkOS Production, never Staging's shared Google credentials."
open_url "https://dashboard.workos.com"
step "Switch the environment selector to Production (activate it if asked)."
step "Organizations: create exactly one organization (e.g. Knowledge Pool)."
step "Authentication → Features: sign-up OFF."
step "Authentication → turn every sign-in method other than Google OFF."
step "Authentication → Providers → Google: open it and leave the page open."
say "That page shows the redirect address Google needs. Copy it for the next stage."
ask WORKOS_GOOGLE_REDIRECT "The redirect URI WorkOS shows for Google:"
write_env WORKOS_GOOGLE_REDIRECT "$WORKOS_GOOGLE_REDIRECT"

stage "Google: OAuth consent screen and client"
open_url "https://console.cloud.google.com/projectcreate"
step "Create a Google Cloud project (e.g. knowledge-pool)."
open_url "https://console.cloud.google.com/auth/branding"
step "OAuth consent screen: app name Knowledge Pool, external, sign-in scopes only (openid, email, profile)."
step "Publish the app to Production so sign-in works for invited people outside test users."
open_url "https://console.cloud.google.com/auth/clients"
step "Create client → Web application, name Knowledge Pool."
step "Authorized redirect URIs: $WORKOS_GOOGLE_REDIRECT"
step "Create, then keep the dialog open: you paste the id and secret into WorkOS next."
pause "Press Enter once the client exists."

stage "WorkOS: Google with your own client"
open_url "https://dashboard.workos.com"
step "Production → Authentication → Providers → Google: choose 'Your app's credentials'."
step "Paste the Google client id and client secret, and enable Google."
note "The Google secret lives at WorkOS only; nothing in the app or Railway needs it."
pause "Press Enter once Google is on with your client."

stage "WorkOS: Connect (MCP) and redirects"
open_url "https://dashboard.workos.com"
step "Connect → Configuration: 'Client ID Metadata Document' ON."
step "Dynamic Client Registration stays OFF."
step "Resource Indicators: add $MCP_URL (path included) and make it the DEFAULT."
note "The bare origin gives invalid_target: the /mcp path matters."
step "Redirects: add $CALLBACK_URL as a redirect URI (make it the default)."
pause "Press Enter once all four are set."

stage "WorkOS: values for the app"
open_url "https://dashboard.workos.com"
step "Production → Domains (or Authentication → AuthKit): copy the AuthKit domain."
ask KP_AUTHKIT_DOMAIN "AuthKit domain (e.g. something.authkit.app):"
write_env KP_AUTHKIT_DOMAIN "$KP_AUTHKIT_DOMAIN"
step "API Keys: copy the Client ID."
ask WORKOS_CLIENT_ID "WorkOS client id (client_...):"
write_env WORKOS_CLIENT_ID "$WORKOS_CLIENT_ID"
step "API Keys: create a key for the app (name it railway-production) and copy it."
ask_secret WORKOS_API_KEY "WorkOS API key (hidden; kept in memory only):"
warn "Save the API key in your password manager now: Railway will seal it and never show it again."
pause "Press Enter once it is in the password manager."

stage "Railway: project, region and spending cap"
open_url "https://railway.com/new"
step "Create an empty project (knowledge-pool), environment production only."
step "Project settings → region EU West (Amsterdam)."
open_url "https://railway.com/account/billing"
step "Plan: Hobby. Usage limits: hard limit 10 dollars."
step "Project settings → Members: you are the only member."
pause "Press Enter once the project exists with the cap set."

stage "Railway: Postgres 18, private only"
step "In the project: Create → Database → PostgreSQL."
step "Postgres service → Settings → Source image: pin the tag to major version 18 (e.g. ...postgres-ssl:18)."
step "Postgres service → Settings → Networking: remove any TCP proxy (no public address)."
step "Name the service Postgres (the app's variable references it by that name)."
pause "Press Enter once Postgres 18 is running with no public address."

stage "Railway: Postgres predicate locks"
say "Jac's graph writes run serializable; the default lock table is too small for them."
step "Open a shell on Postgres from this machine:  railway link  then  railway ssh --service Postgres"
step "In it run:  psql -U postgres -c \"ALTER SYSTEM SET max_pred_locks_per_transaction = 1024\""
step "Restart the Postgres service (Deployments → ⋮ → Restart)."
step "Check:  psql -U postgres -c \"SHOW max_pred_locks_per_transaction\"  answers 1024."
note "If railway ssh is not offered, the Postgres service's Database → Query tab runs the same statement."
ask PRED_LOCKS "What does SHOW max_pred_locks_per_transaction answer now?"
[[ "$PRED_LOCKS" == "1024" ]] || warn "not 1024: run the ALTER SYSTEM again and restart Postgres"
write_env PRED_LOCKS "$PRED_LOCKS"

stage "Railway: the app service"
step "Create → GitHub Repo → $REPO (accept the GitHub permission Railway asks for)."
step "App service → Settings → Source: branch main, 'Wait for CI' ON."
step "Settings → Build: Dockerfile (the repo root's Dockerfile is picked up)."
step "Settings → Deploy: health check path $HEALTH_PATH, restart policy 'On failure'."
step "Don't deploy yet: the variables come next. If it already started a build, let it fail."
pause "Press Enter once the service is linked."

stage "Railway: the app's variables"
say "A fresh cookie password, generated here. Save it to your password manager first."
WORKOS_COOKIE_PASSWORD=$(openssl rand -base64 32)
printf '\n  %sWORKOS_COOKIE_PASSWORD%s  %s\n\n' "$BOLD" "$RESET" "$WORKOS_COOKIE_PASSWORD"
pause "Press Enter once the cookie password is in the password manager."
_clear
printf '\n  %sApp service → Variables → Raw editor. Paste these:%s\n\n' "$BOLD" "$RESET"
printf '  JAC_DB_URL=${{Postgres.DATABASE_URL}}\n'
printf '  KP_AUTHKIT_DOMAIN=%s\n' "$KP_AUTHKIT_DOMAIN"
printf '  KP_PUBLIC_MCP_URL=%s\n' "$MCP_URL"
printf '  WORKOS_CLIENT_ID=%s\n' "$WORKOS_CLIENT_ID"
printf '  WORKOS_API_KEY=%s\n' "$WORKOS_API_KEY"
printf '  WORKOS_COOKIE_PASSWORD=%s\n\n' "$WORKOS_COOKIE_PASSWORD"
step "Then on WORKOS_API_KEY and WORKOS_COOKIE_PASSWORD: ⋮ → Seal."
step "Check JAC_DB_URL resolves to the private address (postgres.railway.internal), not a proxy."
pause "Press Enter once the variables are set and the two secrets sealed."
unset WORKOS_API_KEY WORKOS_COOKIE_PASSWORD
_clear

stage "Railway: custom domain and DNS"
step "App service → Settings → Networking → Custom domain: $APP_HOST (port: the one Railway suggests)."
step "Railway shows a CNAME (and a TXT verification record). Copy them."
open_url "https://hpanel.hostinger.com/domains"
step "engi.ai → DNS records: add exactly those records for the knowledge-pool name, no proxy."
step "Wait for Railway to show the domain verified and the certificate issued."
pause "Press Enter once Railway shows the domain as active."

stage "Notifications for failures"
open_url "https://railway.com/account/notifications"
step "Railway: email on deployment failures ON."
open_url "https://github.com/settings/notifications"
step "GitHub → Actions: notifications for failed workflows ON (email)."
pause

stage "GitHub: Railway project token"
say "For the weekly catalogue rebuild (#137): a token that can only deploy this project."
step "Railway project → Settings → Tokens: create a token for production, name it github-weekly-rebuild."
ask_secret RAILWAY_TOKEN "Paste the project token (hidden):"
set_secret RAILWAY_TOKEN "$RAILWAY_TOKEN"
unset RAILWAY_TOKEN
note "Step 28 of #109 (running the weekly rebuild by hand once) is checked in #137."
pause

# ── B. First deploy ───────────────────────────────────────────────────────

stage "First deploy: Test, build, health"
say "Push to main (merge the release PR). Railway waits for Test, then builds and checks health."
open_url "https://github.com/$REPO/actions/workflows/test.yml"
step "Watch Test pass on main, then the Railway build and health check."
pause "Press Enter once Railway shows the deployment Active (the wizard then polls $HEALTH_PATH)."
health=""
for _ in $(seq 1 30); do
  health=$(curl -s --max-time 10 "$APP_URL$HEALTH_PATH" || true)
  [[ "$health" == "ok" ]] && break
  sleep 10
done
expect_status "health $HEALTH_PATH" "ok" "$health"

stage "First deploy: what strangers can reach"
for p in /docs /graph /admin /walkers /functions /user/register; do
  expect_status "GET $p" 404 "$(status_of GET "$p")"
done
page=$(status_of GET / -H 'Accept: text/html')
[[ "$page" =~ ^30[1-8]$ ]] && page=redirect
expect_status "page load with no session" redirect "$page"
expect_status "POST /mcp with no token" 401 "$(status_of POST /mcp -H 'Content-Type: application/json' -d '{}')"
say "A forged X-Real-IP: 40 requests with no token, each claiming a different address."
note "If Railway overwrites the header they all count as you, and the 30-a-minute limit refuses some."
refused=0
for i in $(seq 1 40); do
  [[ "$(status_of POST /mcp -H "X-Real-IP: 203.0.113.$i" -H 'Content-Type: application/json' -d '{}')" == "429" ]] && refused=$((refused + 1))
done
if (( refused > 0 )); then
  record "Forged X-Real-IP" "overwritten by Railway's edge: $refused of 40 requests with distinct forged addresses were refused with 429"
else
  record "Forged X-Real-IP" "NOT overwritten: 40 requests with distinct forged addresses were all let through; the address limit can be dodged"
  warn "the address limit trusts a forged header: open an issue before inviting anyone"
fi
note "Your address is now refused for up to a minute; the next stage waits for it."
pause

stage "First deploy: sign-in"
note "Waiting a minute for the address limit from the last stage to refill..."
sleep 60
open_url "https://dashboard.workos.com"
step "Production → Organizations → your organization → invite your own Google address."
open_url "$APP_URL"
step "Accept the invite, sign in with Google: the first run of the production Google client."
step "Open DevTools → Network before reloading, reload once, read the request count at the bottom."
ask PAGE_REQUESTS "How many requests did the first page load make?"
if [[ "$PAGE_REQUESTS" =~ ^[0-9]+$ ]] && (( PAGE_REQUESTS < 300 )); then
  record "First page load" "$PAGE_REQUESTS requests (under the 300-a-minute user limit)"
else
  record "First page load" "$PAGE_REQUESTS requests: at or over the 300-a-minute user limit"
fi
step "In a private window, sign in with a Google account that was NOT invited."
if confirm "Was the uninvited account refused?"; then record "Uninvited account" "refused"
else record "Uninvited account" "NOT refused: check sign-up is off at WorkOS"; fi

stage "First deploy: the claude.ai connector"
open_url "https://claude.ai/settings/connectors"
step "Add custom connector: $MCP_URL. Connect, sign in with Google."
step "In a chat: create a deck. Then reload $APP_URL and see the deck in the web page."
if confirm "Did the deck made in claude.ai show in the web page?"; then record "claude.ai connector" "works; its deck shows in the web page"
else record "claude.ai connector" "deck did NOT show in the web page"; fi
say "MCP Apps views: open a deck view in claude.ai and act in it (e.g. a button that calls a tool)."
step "Railway → app → Logs: the tool call from the view is logged under your user, not refused."
ask_note "MCP Apps tools/call" "Did the view's tools/call arrive on the signed-in connection? (what you saw):"
say "How claude.ai shows a 429: set KP_RATE_LIMIT_USER=5 on Railway, deploy, make 6 calls fast."
step "Then remove KP_RATE_LIMIT_USER and deploy again."
ask_note "429 in claude.ai" "How did claude.ai show the 429?"

stage "First deploy: display name and Claude Code"
open_url "https://dashboard.workos.com"
step "Production → Authentication → JWT template (Sessions): can it add the user's name to access tokens?"
step "Connector tokens come from Connect: check whether the template applies to those too."
ask_note "Display name in connector tokens" "Can a WorkOS token template carry the display name in connector tokens?"
say "Claude Code over HTTP:"
step "claude mcp add --transport http knowledge-pool $MCP_URL   then /mcp in Claude Code to sign in."
step "Ask it to list your decks."
ask_note "Claude Code over HTTP" "What happened?"

stage "Runbook, and posting the notes"
say "Every deploy: a failed Test or build emails you and the old version keeps serving."
say "  Fix forward, or Railway → Deployments → the previous one → Rollback."
say "Rotating a secret: generate the new value, save it to the password manager, replace the"
say "  sealed variable, deploy the staged change. For the WorkOS API key, create the new key at"
say "  WorkOS first and delete the old one once the deploy is healthy. A new cookie password"
say "  signs every browser out; connectors are unaffected."
printf '\n'
[[ -f "$NOTES_FILE" ]] && sed 's/^/  /' "$NOTES_FILE"
printf '\n'
if confirm "Post these notes as a comment on #$ISSUE?"; then
  gh issue comment "$ISSUE" -R "$REPO" --body-file "$NOTES_FILE" && note "posted; the notes stay at $NOTES_FILE"
else
  note "not posted; they are at $NOTES_FILE"
fi
pause

finish
